    }

    // dp[i][p] = can we partition prefix [0..i-1] into p subsegments (p mod 2)
    // p=0 means even number of subsegments, p=1 means odd
    vector<vector<bool>> dp(n + 1, vector<bool>(2, false));
    dp[0][0] = true; // 0 subsegments, even count

    for (int i = 0; i < n; i++) {
        for (int p = 0; p < 2; p++) {
            if (!dp[i][p]) continue;
            // Try all possible subsegments starting at i
            for (int j = i; j < n; j++) {
                int len = j - i + 1;
                if (len % 2 == 0) continue; // must be odd length
                if (a[i] % 2 == 0 || a[j] % 2 == 0) continue; // must start and end with odd
                // This subsegment is valid, transition
                dp[j + 1][(p + 1) % 2] = true;
            }
        }
    }

    cout << (dp[n][1] ? "Yes" : "No") << endl;
