    for (int i = 0; i < n; ++i) {
        for (int j = 0; j <= i; ++j) {
            // Check if [j, i] is a valid subsegment
            if (a[j] % 2 == 1 && a[i] % 2 == 1 && (i - j + 1) % 2 == 1) {
